<?php
require_once __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../../includes/functions.php'; require_admin('../login.php');
$service_query = $pdo->prepare('SELECT id, name, type, image, status, is_featured, created_at FROM services ORDER BY created_at DESC'); $service_query->execute(); $services = $service_query->fetchAll(); $page_title = 'Services'; require __DIR__ . '/../includes/header.php';
?><div class="admin-title"><h1>Services</h1><a class="button" href="create.php">Add service <span>+</span></a></div><div class="table-responsive"><table class="admin-table"><thead><tr><th>ID</th><th>Image</th><th>Name</th><th>Type</th><th>Status</th><th>Featured</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach ($services as $service): ?><tr><td><?= (int)$service['id'] ?></td><td><img src="<?= e($service['image'] ? '../../uploads/dates/' . rawurlencode(basename($service['image'])) : '../../assets/images/date-fruit.svg') ?>" alt="" width="64" height="48" style="object-fit:cover"></td><td><?= e($service['name']) ?></td><td><?= e(ucfirst($service['type'])) ?></td><td><?= e(ucfirst($service['status'])) ?></td><td><?= $service['is_featured'] ? 'Yes' : 'No' ?></td><td><?= e(date('d M Y', strtotime($service['created_at']))) ?></td><td><a href="view.php?id=<?= (int)$service['id'] ?>">View</a> · <a href="edit.php?id=<?= (int)$service['id'] ?>">Edit</a><form method="post" action="delete.php" class="d-inline" data-confirm-delete="Delete this service?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$service['id'] ?>"><button type="submit" class="btn btn-link p-0 align-baseline text-danger">Delete</button></form></td></tr><?php endforeach; ?><?php if (!$services): ?><tr><td colspan="8">No services found.</td></tr><?php endif; ?></tbody></table></div><?php require __DIR__ . '/../includes/footer.php'; ?>